#!/usr/bin/env bash
# Generated by shopfloor. Puts the rules and skills in this folder where coding agents read them.
set -euo pipefail

# The generator fills these in from the recipe.
PROVIDERS=()
SKILLS=()

usage() {
  cat <<'USAGE'
Puts the rules and skills in this folder where coding agents read them.

  ./install.sh project [folder]   one repository (default: the current folder)
  ./install.sh machine            every project on this machine

Add --dry-run to see what would change, or --uninstall to remove the rules
and skills this script added. Files it changes are copied to a backup folder first.

Add --with-skills to download the skills the rules name from their own
repositories, where they are missing. It needs git, and never replaces a skill.
USAGE
}

HERE=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd -P)
START='<!-- shopfloor:start -->'
END='<!-- shopfloor:end -->'
BACKUP=${XDG_STATE_HOME:-$HOME/.local/state}/shopfloor/backup-$(date +%Y%m%d-%H%M%S)-$$

# The rules files and skills folders this run installs into, and where repositories it downloads are kept meanwhile.
RULES_FILES=()
SKILL_DIRS=()
CLONES=""
trap 'if [[ -n $CLONES ]]; then rm -rf "$CLONES"; fi' EXIT

mode="" folder="" dry=0 uninstall=0 with_skills=0 skipped=0
for arg in "$@"; do
  case $arg in
    project | machine) mode=$arg ;;
    --dry-run) dry=1 ;;
    --uninstall) uninstall=1 ;;
    --with-skills) with_skills=1 ;;
    -*)
      echo "install.sh: unknown option $arg" >&2
      exit 2
      ;;
    *) folder=$arg ;;
  esac
done
if [[ -z $mode ]]; then
  usage
  exit 2
fi

say() { printf '%-8s %s\n' "$1" "$2"; }

uses() {
  case " ${PROVIDERS[*]-} " in
    *" $1 "*) return 0 ;;
  esac
  return 1
}

# Copies a file aside before it is changed.
backup() {
  [[ -f $1 ]] || return 0
  mkdir -p "$BACKUP$(dirname "$1")"
  cp -p "$1" "$BACKUP$1"
}

# Prints a rules file without our block, and without the blank lines left in front of it.
without_block() {
  awk -v start="$START" -v end="$END" '
    $0 == start { skip = 1 }
    !skip {
      if ($0 ~ /^[[:space:]]*$/) blank = blank $0 "\n"
      else { printf "%s", blank; blank = ""; print }
    }
    $0 == end { skip = 0 }
  ' "$1"
}

# True when every start line in a rules file is followed by an end line before the next start.
well_formed() {
  awk -v start="$START" -v end="$END" '
    $0 == start { if (open) bad = 1; open = 1 }
    $0 == end { if (!open) bad = 1; open = 0 }
    END { exit (bad || open) ? 1 : 0 }
  ' "$1"
}

# Removes the files this script puts in a skill folder, and the folder if nothing else is in it.
remove_skill() {
  backup "$1/SKILL.md"
  rm -f "$1/SKILL.md" "$1/.shopfloor"
  rmdir "$1" 2>/dev/null || say note "$1 holds other files, so the folder was left in place."
}

write_rules() {
  local file=$1 tmp
  if [[ -L $file ]]; then
    if ((!uninstall)); then
      say skip "$file is a symlink, so the rules were not added. Put the contents of rules.md, which View files on the site shows, into the file it points at."
      skipped=1
    elif [[ -f $file ]] && grep -qxF -- "$START" "$file"; then
      say skip "$file is a symlink, so the rules were not removed. Take the block between the two shopfloor lines out of the file it points at."
      skipped=1
    fi
    return 0
  fi
  if [[ -f $file ]] && ! well_formed "$file"; then
    say skip "$file has a shopfloor block with a missing or misplaced start or end line. Fix it by hand first."
    skipped=1
    return 0
  fi
  if ((uninstall)); then
    if [[ ! -f $file ]] || ! grep -qxF -- "$START" "$file"; then return 0; fi
    say remove "rules from $file"
    if ((dry)); then return 0; fi
    backup "$file"
    tmp=$(mktemp "${TMPDIR:-/tmp}/shopfloor.XXXXXX")
    without_block "$file" >"$tmp"
    cat "$tmp" >"$file"
    rm -f "$tmp"
    if [[ ! -s $file ]]; then rm -f "$file"; fi
    return 0
  fi
  tmp=$(mktemp "${TMPDIR:-/tmp}/shopfloor.XXXXXX")
  if [[ -f $file ]]; then without_block "$file" >"$tmp"; fi
  if [[ -s $tmp ]]; then echo >>"$tmp"; fi
  cat "$HERE/rules.md" >>"$tmp"
  if [[ -f $file ]] && cmp -s "$tmp" "$file"; then
    say same "rules in $file"
  else
    say write "rules to $file"
    if ((!dry)); then
      mkdir -p "$(dirname "$file")"
      backup "$file"
      cat "$tmp" >"$file"
    fi
  fi
  rm -f "$tmp"
}

# Copies our skills into one skills folder.
install_skills() {
  local dir=$1 source name old
  if ((!uninstall)); then
    case " ${SKILL_DIRS[*]-} " in
      *" $dir "*) ;;
      *) SKILL_DIRS+=("$dir") ;;
    esac
  fi
  # Skills an earlier recipe put here and this one leaves out, or all of ours on uninstall.
  for old in "$dir"/shopfloor-*/; do
    [[ -f ${old}.shopfloor ]] || continue
    name=$(basename "$old")
    # A link points at a skill kept somewhere else, which is not this folder's to change.
    if [[ -L $dir/$name ]]; then continue; fi
    if ((!uninstall)) && [[ -f $HERE/skills/$name/SKILL.md ]]; then continue; fi
    say remove "$dir/$name"
    if ((!dry)); then remove_skill "$dir/$name"; fi
  done
  if ((uninstall)); then return 0; fi
  for source in "$HERE"/skills/*/; do
    [[ -f ${source}SKILL.md ]] || continue
    name=$(basename "$source")
    if [[ -L $dir/$name ]]; then
      say skip "$dir/$name is a symlink, so the skill it points at was left as it is."
      continue
    fi
    if [[ -e $dir/$name && ! -f $dir/$name/.shopfloor ]]; then
      say skip "$dir/$name exists and this script did not put it there."
      continue
    fi
    if cmp -s "${source}SKILL.md" "$dir/$name/SKILL.md"; then
      say same "$dir/$name"
      continue
    fi
    say write "$dir/$name"
    if ((dry)); then continue; fi
    mkdir -p "$dir/$name"
    # An installed copy that differs may hold someone's edits, so it goes to the backup folder first.
    backup "$dir/$name/SKILL.md"
    cp "${source}SKILL.md" "$dir/$name/SKILL.md"
    : >"$dir/$name/.shopfloor"
  done
}

# True when the first path is one of the others, by name or because one is a link to the other.
among() {
  local path=$1 other
  shift
  for other in ${1+"$@"}; do
    if [[ $path == "$other" || $path -ef $other ]]; then return 0; fi
  done
  return 1
}

# Where one provider reads its machine-wide files. Sets rules, which is empty when no such file is known, and skills.
places() {
  case $1 in
    claude)
      rules=${CLAUDE_CONFIG_DIR:-$HOME/.claude}/CLAUDE.md
      skills=${CLAUDE_CONFIG_DIR:-$HOME/.claude}/skills
      ;;
    codex)
      rules=${CODEX_HOME:-$HOME/.codex}/AGENTS.md
      skills=$HOME/.agents/skills
      ;;
    antigravity)
      rules=$HOME/.gemini/AGENTS.md
      skills=$HOME/.gemini/config/skills
      ;;
    *)
      rules=""
      skills=$HOME/.agents/skills
      ;;
  esac
}

# Copies one skill from its own repository into one skills folder, the way its authors say to install it.
fetch_skill() {
  local name=$1 repo=$2 dir=$3 clone
  if ((dry)); then
    say fetch "$dir/$name from $repo"
    return 0
  fi
  if ! command -v git >/dev/null; then
    say missing "The $name skill needs git to download. Get it from $repo"
    return 0
  fi
  if [[ -z $CLONES ]]; then CLONES=$(mktemp -d "${TMPDIR:-/tmp}/shopfloor.XXXXXX"); fi
  clone=$CLONES/${repo//[^A-Za-z0-9]/_}
  if [[ ! -e $clone ]]; then
    # Only the skills folder is wanted. A server or git that cannot send part of a repository sends all of it.
    GIT_TERMINAL_PROMPT=0 git clone --quiet --depth 1 --filter=blob:none --sparse -- "$repo" "$clone" 2>/dev/null &&
      git -C "$clone" sparse-checkout set skills 2>/dev/null ||
      {
        rm -rf "$clone"
        GIT_TERMINAL_PROMPT=0 git clone --quiet --depth 1 -- "$repo" "$clone" 2>/dev/null
      } ||
      mkdir -p "$clone"
  fi
  if [[ ! -d $clone/.git ]]; then
    say missing "The $name skill could not be downloaded. Get it from $repo"
  elif [[ -L $clone/skills/$name || ! -f $clone/skills/$name/SKILL.md ]]; then
    say missing "The $name skill is not at skills/$name in its repository. Get it from $repo"
  else
    say fetch "$dir/$name from $repo"
    mkdir -p "$dir"
    cp -R "$clone/skills/$name" "$dir/$name"
  fi
}

# With --with-skills, adds each skill the rules name to the folders this run installs into.
# Otherwise names the skills that are in none of those folders, the given ones or the machine-wide ones.
# shortcut: a skill installed for one agent counts as installed for all, upgrade if that misleads.
check_skills() {
  local entry name repo dir found
  for entry in ${SKILLS[@]+"${SKILLS[@]}"}; do
    name=${entry%% *}
    repo=${entry#* }
    if ((with_skills)); then
      for dir in ${SKILL_DIRS[@]+"${SKILL_DIRS[@]}"}; do
        if [[ ! -e $dir/$name && ! -L $dir/$name ]]; then fetch_skill "$name" "$repo" "$dir"; fi
      done
      continue
    fi
    found=0
    for dir in ${SKILL_DIRS[@]+"${SKILL_DIRS[@]}"} ${1+"$@"} "${CLAUDE_CONFIG_DIR:-$HOME/.claude}/skills" "$HOME/.agents/skills" "$HOME/.gemini/config/skills"; do
      if [[ -e $dir/$name ]]; then found=1; fi
    done
    if ((!found)); then say missing "The $name skill is not installed. Get it from $repo"; fi
  done
}

if [[ $mode == project ]]; then
  root=${folder:-$PWD}
  if [[ ! -d $root ]]; then
    echo "install.sh: $root is not a folder" >&2
    exit 1
  fi
  root=$(cd "$root" && pwd -P)
  write_rules "$root/AGENTS.md"
  install_skills "$root/.agents/skills"
  # Claude Code reads CLAUDE.md and .claude/skills, not AGENTS.md and .agents/skills.
  if [[ -d $root/.claude/skills && ! -L $root/.claude/skills ]]; then
    install_skills "$root/.claude/skills"
  elif uses claude && ((!uninstall)) && [[ ! -e $root/.claude/skills && ! -L $root/.claude/skills ]]; then
    say link "$root/.claude/skills to ../.agents/skills"
    if ((!dry)); then
      mkdir -p "$root/.claude"
      ln -s ../.agents/skills "$root/.claude/skills"
    fi
  fi
  if uses claude && ((!uninstall)); then
    if [[ ! -e $root/CLAUDE.md && ! -L $root/CLAUDE.md ]]; then
      say write "$root/CLAUDE.md, which points at AGENTS.md"
      if ((!dry)); then printf '@AGENTS.md\n' >"$root/CLAUDE.md"; fi
    elif [[ ! $root/CLAUDE.md -ef $root/AGENTS.md ]] && ! grep -q 'AGENTS\.md' "$root/CLAUDE.md" 2>/dev/null; then
      say note "$root/CLAUDE.md does not load AGENTS.md. Add a line that says @AGENTS.md"
    fi
  fi
  if ((!uninstall)); then check_skills "$root/.claude/skills"; fi
else
  if ((${#PROVIDERS[@]} == 0)) && ((!uninstall)); then
    say note "No machine-wide rules file is known for this recipe's providers, so nothing was changed. Install it for one project instead."
    exit 0
  fi
  if ((!uninstall)); then
    for provider in ${PROVIDERS[@]+"${PROVIDERS[@]}"}; do
      places "$provider"
      if [[ -n $rules ]]; then
        RULES_FILES+=("$rules")
        write_rules "$rules"
      else
        say note "Muse Code has no documented machine-wide rules file. Install for one project to give it the rules."
      fi
      install_skills "$skills"
    done
  fi
  # A provider this recipe leaves out may still hold an earlier recipe's rules and skills, and would go on
  # following them. They are removed, as is everything on an uninstall, whichever recipe this script is from.
  # A place this run installed into is left alone, also when it is reached under another name.
  asked=$uninstall
  uninstall=1
  cleaned=()
  for provider in claude codex antigravity muse; do
    if ((!asked)) && uses "$provider"; then continue; fi
    places "$provider"
    if [[ -n $rules ]] && ! among "$rules" ${RULES_FILES[@]+"${RULES_FILES[@]}"}; then write_rules "$rules"; fi
    if ! among "$skills" ${SKILL_DIRS[@]+"${SKILL_DIRS[@]}"} ${cleaned[@]+"${cleaned[@]}"}; then
      install_skills "$skills"
      cleaned+=("$skills")
    fi
  done
  uninstall=$asked
  if ((!uninstall)); then check_skills; fi
fi

if ((dry)); then
  say ok "Dry run. Nothing was changed."
else
  if [[ -d $BACKUP ]]; then say backup "$BACKUP"; fi
  if ((skipped)); then
    say note "Some rules files were left as they were. See the lines marked skip."
  else
    say ok "Start a new thread to load the change. Running threads keep what they loaded."
  fi
fi
